/// Converts a memory keywords value to its keywords (eg. `dword ptr`)
constexpr FormatterStringSlice get_memory_keywords(const FormatterArrayConstants& ac, std::uint32_t memory_keywords) noexcept {
	switch (memory_keywords) {
	case 0x00: return ac.nothing;
	case 0x01: return ac.byte_ptr;
	case 0x02: return ac.dword_ptr;
	case 0x03: return ac.fpuenv14_ptr;
	case 0x04: return ac.fpuenv28_ptr;
	case 0x05: return ac.fpustate108_ptr;
	case 0x06: return ac.fpustate94_ptr;
	case 0x07: return ac.fword_ptr;
	case 0x08: return ac.qword_ptr;
	case 0x09: return ac.tbyte_ptr;
	case 0x0A: return ac.word_ptr;
	case 0x0B: return ac.xmmword_ptr;
	case 0x0C: return ac.ymmword_ptr;
	case 0x0D: return ac.zmmword_ptr;
	case 0x0E: return ac.mem384_ptr;
	default: ICED_UNREACHABLE();
	}
}

/// Converts a `BroadcastToKind` value to its string (eg. `1to8`)
constexpr const FormatterString& get_bcst_to_string(const FormatterConstants& c, std::uint32_t bcst_to_kind) noexcept {
	switch (bcst_to_kind) {
	case 0x00: return c.empty;
	case 0x01: return c.b1to2;
	case 0x02: return c.b1to4;
	case 0x03: return c.b1to8;
	case 0x04: return c.b1to16;
	case 0x05: return c.b1to32;
	default: ICED_UNREACHABLE();
	}
}

